-- Floating cheat sheet for the Karabiner hyper key bindings.
-- Karabiner opens hammerspoon://toggle-cheatsheet on Hyper + Backspace.
-- The page is generated by `yarn build` into ../cheatsheet.html.

local scriptDirectory = debug.getinfo(1, "S").source:sub(2):match("(.*/)")
local htmlPath = hs.fs.pathToAbsolute(scriptDirectory .. "../cheatsheet.html")
local width, height = 980, 620

-- Build the panel once and keep it hidden, so showing it is instant.
local view = hs.webview.new({ x = 0, y = 0, w = width, h = height })
  :windowStyle({ "borderless" })
  :transparent(true)
  :level(hs.drawing.windowLevels.modalPanel)
  :behaviorAsLabels({ "canJoinAllSpaces", "fullScreenAuxiliary" })
  :url("file://" .. htmlPath)

local isVisible = false

local function hideCheatSheet()
  view:hide()
  isVisible = false
  CheatSheetEscapeHotkey:disable()
end

local function showCheatSheet()
  local screen = hs.screen.mainScreen():frame()
  view:frame({
    x = screen.x + (screen.w - width) / 2,
    y = screen.y + (screen.h - height) / 2,
    w = width,
    h = height,
  })
  view:show()
  isVisible = true
  CheatSheetEscapeHotkey:enable()
end

-- Globals, so Hammerspoon does not garbage collect them.
CheatSheetEscapeHotkey = hs.hotkey.new({}, "escape", hideCheatSheet)

-- Reload the page in the background after `yarn build` changes it.
CheatSheetWatcher = hs.pathwatcher.new(htmlPath, function()
  view:reload()
end):start()

hs.urlevent.bind("toggle-cheatsheet", function()
  if isVisible then hideCheatSheet() else showCheatSheet() end
end)
